(function(){'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=()=>window.NEXZOPersonalization;
const recById=id=>(api()?.snapshot()?.recommendations||[]).find(r=>r.id===id);
function plannerTaskFrom(r){return {id:`rec_${r.id}_${Date.now()}`,title:(r.suggestedTasks||[])[0]||r.action,subject:r.subject||'General',type:'Personalized',difficulty:r.type==='foundation'?'Beginner':r.type==='application'?'Advanced':'Intermediate',duration:Number(r.durationMinutes)||30,completed:false,source:'personalized-recommender',recommendationId:r.id,createdAtMs:Date.now(),updatedAtMs:Date.now()}}
function addPlanner(r){const store=window.NEXZOTaskStore;if(!store?.upsert){window.NEXZOShell?.toast?.('Planner is still loading. Try once more.','error');return}store.upsert(plannerTaskFrom(r),{cloud:true,immediate:true});window.NEXZOShell?.toast?.(`${r.topic} added to Planner.`,'success')}
function studyNow(r){localStorage.setItem('nexzo.ai.launch',JSON.stringify({mode:'explain',prompt:`I need a ${r.durationMinutes}-minute personalized study session for ${r.topic} in ${r.subject}. Start with this task: ${(r.suggestedTasks||[])[0]||r.action}. Then give practice and a checkpoint. My recommendation match is ${r.matchScore}%. Use my saved learning profile, mastery, Planner activity and goals.`,recommendationId:r.id,at:Date.now()}));location.href='ai-assistant.html'}
function render(){const box=document.getElementById('dashPersonalizedActions'),p=api();if(!box||!p)return;const s=p.snapshot(),rows=s.recommendations||[],ml=s.modelSummary?.ml||{};
box.innerHTML=`<div class="nx-rec-modelbar"><span>🧠 ${ml.active?'Hybrid ML ranking active':'Contextual ranking · ML learning from feedback'}</span><small>${ml.active?`${ml.trainingSamples} feedback samples`: `Cold start: ${ml.trainingSamples||0}/6 feedback samples`}</small></div>`+(rows.length?rows.slice(0,3).map((r,i)=>`<article class="nx-rec-row nx-dash-rec-action" data-open-rec="${esc(r.id)}" tabindex="0" role="button" aria-label="Open ${esc(r.topic)} recommendation"><div class="nx-rec-head"><div><b>${i+1}. ${esc(r.topic)}</b><small> · ${esc(r.subject)}</small></div><span class="nx-match">${r.matchScore||0}% match</span></div><p class="nx-rec-action">${esc(r.action)}</p><div class="nx-rec-meta"><span>⏱ ${r.durationMinutes} min</span>${r.assessed?`<span>📊 Mastery ${r.mastery}%</span>`:'<span>🧭 Diagnostic recommended</span>'}<span>⚙ ${r.rankingMode==='hybrid-ml'?'Hybrid ML':'Contextual model'}</span></div><ul class="nx-why">${(r.why||[]).slice(0,2).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="nx-rec-dashboard-actions"><button type="button" class="nx-rec-primary" data-study-rec="${esc(r.id)}">${esc(r.actionLabel||'Start now')} →</button><button type="button" data-plan-rec="${esc(r.id)}">+ Planner</button><button type="button" data-feedback-rec="${esc(r.id)}:useful">👍 Useful</button><button type="button" data-feedback-rec="${esc(r.id)}:not-relevant">✕ Not relevant</button></div></article>`).join(''):'<div class="nx-runtime-empty">Add subjects, goals or Planner activity to generate personalized recommendations.</div>')}
function wire(){const box=document.getElementById('dashPersonalizedActions');if(!box||box.dataset.wired)return;box.dataset.wired='1';box.addEventListener('click',e=>{const study=e.target.closest('[data-study-rec]'),plan=e.target.closest('[data-plan-rec]'),fb=e.target.closest('[data-feedback-rec]');if(study){e.stopPropagation();const r=recById(study.dataset.studyRec);if(r)studyNow(r);return}if(plan){e.stopPropagation();const r=recById(plan.dataset.planRec);if(r)addPlanner(r);return}if(fb){e.stopPropagation();const [id,value]=fb.dataset.feedbackRec.split(':');api()?.feedback?.(id,value);window.NEXZOShell?.toast?.('Feedback saved — ranking will adapt.','success');render();return}const row=e.target.closest('[data-open-rec]');if(row){const r=recById(row.dataset.openRec);if(r)studyNow(r)}});box.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open-rec]')){e.preventDefault();const r=recById(e.target.dataset.openRec);if(r)studyNow(r)}})}
function init(){wire();render()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();['nexzo:personalization-ready','nexzo:personalization-updated','nexzo:personalization-sync'].forEach(n=>window.addEventListener(n,render));})();
